-- Netherlands deep-dive ES/DE/FR translations (completing 219). INSERT OR IGNORE.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'B2B voluntario (adopción de Peppol impulsada por el mercado) — B2G obligatorio desde 2017/2019', 'Esta página de análisis refleja la orientación pública y las noticias disponibles a agosto de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. La postura del gabinete neerlandés sobre un mandato B2B nacional seguía sin decidirse en el momento de redactar esto, con una posición formal prevista para el verano de 2026 y un anteproyecto de ley planeado para el cuarto trimestre de 2026 — confirme el estado actual directamente con la Belastingdienst o Logius antes de basarse en ella.', 'Los Países Bajos han seguido un camino impulsado por el mercado que la mayor parte de Europa no ha tomado: la facturación electrónica B2G es obligatoria desde 2017, pero el B2B sigue siendo voluntario hoy, respaldado por una adopción de Peppol inusualmente alta. Eso está ahora bajo revisión activa — un informe consultivo de marzo de 2026 recomendó un mandato nacional, y se espera la decisión del gabinete de forma inminente, frente a un suelo firme de derecho de la UE de julio de 2030 para el B2B transfronterizo, sea cual sea el resultado.', 'Donde ocurre el intercambio B2G, funciona sobre Peppol BIS 3.0 / SI-UBL 2.0 — el mismo estándar utilizado voluntariamente por la mayor parte del tráfico B2B actual, de modo que las empresas que ya intercambian facturas Peppol con contrapartes gubernamentales están en gran medida preadaptadas para lo que traiga la decisión sobre el B2B nacional.', 'Tres canales dan servicio al tráfico B2G hoy — la red Peppol (recomendada), Digipoort (una pasarela directa para proveedores de gran volumen) y el Portal de Proveedores del Gobierno (entrada manual para proveedores de bajo volumen) — mientras que el intercambio B2B ocurre por acuerdo mutuo, normalmente también sobre Peppol.', 'Dado que el B2B es voluntario hoy, la mayor parte del trabajo a corto plazo de las empresas tiene que ver con la preparación más que con el cumplimiento: confirmar la capacidad Peppol, seguir la decisión del gabinete sobre el alcance y prepararse para el suelo confirmado de la UE de 2030 para el transfronterizo, sea cual sea el alcance final del mandato nacional.', 'No existe un régimen sancionador B2B nacional hoy porque no existe un mandato B2B nacional — pero ya se aplican dos presiones reales: la exclusión contractual (contrapartes que exigen cada vez más Peppol para poder hacer negocios) y el suelo de la UE que se acerca, aplicable con independencia del resultado nacional.', 'Los Países Bajos han aplicado la facturación electrónica B2G obligatoria desde 2017 (gobierno central) y 2019 (todos los organismos públicos), pero el B2B sigue siendo voluntario — un enfoque deliberadamente impulsado por el mercado con una adopción de Peppol inusualmente alta. Un informe encargado por el gobierno en marzo de 2026 recomendó ampliar el mandato al B2B nacional sobre Peppol, escalonado entre 2030 y 2032; se esperaba la decisión formal del gabinete para el verano de 2026, con un anteproyecto de ley previsto para el cuarto trimestre de 2026. Por separado, el mandato de ViDA de facturación electrónica y reporte transfronterizos B2B es derecho de la UE confirmado desde el 1 de julio de 2030, con independencia del resultado nacional.', '🌷' FROM countries WHERE name_en = 'Netherlands';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Freiwilliges B2B (marktgetriebene Peppol-Verbreitung) — B2G verpflichtend seit 2017/2019', 'Diese Länderanalyse spiegelt öffentlich verfügbare Hinweise und Berichterstattung mit Stand August 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Die Haltung des niederländischen Kabinetts zu einer inländischen B2B-Pflicht war zum Zeitpunkt der Abfassung noch nicht entschieden, eine formelle Positionierung wurde für den Sommer 2026 erwartet, ein Gesetzentwurf war für das vierte Quartal 2026 geplant — bestätigen Sie den aktuellen Stand direkt bei der Belastingdienst oder Logius, bevor Sie darauf aufbauen.', 'Die Niederlande haben einen marktgetriebenen Weg eingeschlagen, den die meisten europäischen Länder nicht gegangen sind: B2G-E-Rechnung ist seit 2017 verpflichtend, B2B bleibt jedoch bis heute freiwillig, gestützt auf eine ungewöhnlich hohe Peppol-Verbreitung. Das wird nun aktiv überprüft — ein Gutachten vom März 2026 empfahl eine inländische Pflicht, und die Entscheidung des Kabinetts wird unmittelbar erwartet, vor dem Hintergrund einer festen EU-rechtlichen Untergrenze ab Juli 2030 für grenzüberschreitendes B2B, unabhängig vom Ausgang.', 'Wo B2G-Austausch stattfindet, läuft er über Peppol BIS 3.0 / SI-UBL 2.0 — denselben Standard, der heute freiwillig für den Großteil des B2B-Verkehrs genutzt wird, sodass Unternehmen, die bereits Peppol-Rechnungen mit staatlichen Gegenparteien austauschen, für das, was die inländische B2B-Entscheidung bringt, weitgehend vorbereitet sind.', 'Drei Kanäle bedienen heute den B2G-Verkehr — das Peppol-Netzwerk (empfohlen), Digipoort (eine Direktschnittstelle für Lieferanten mit hohem Volumen) und das Regierungslieferantenportal (manuelle Eingabe für Lieferanten mit geringem Volumen) — während der B2B-Austausch nach gegenseitiger Vereinbarung erfolgt, meist ebenfalls über Peppol.', 'Da B2B heute freiwillig ist, geht es bei der kurzfristigen Arbeit der meisten Unternehmen eher um Vorbereitung als um Compliance: Peppol-Fähigkeit bestätigen, die Umfangsentscheidung des Kabinetts beobachten und sich auf die bestätigte EU-Untergrenze von 2030 für grenzüberschreitende Geschäfte vorbereiten, unabhängig davon, was die inländische Pflicht letztlich abdeckt.', 'Es gibt heute kein inländisches B2B-Sanktionsregime, weil es keine inländische B2B-Pflicht gibt — aber zwei reale Drucksituationen bestehen bereits: vertraglicher Ausschluss (Geschäftspartner verlangen zunehmend Peppol-Fähigkeit) und die näherrückende EU-Untergrenze, die unabhängig vom inländischen Ausgang gilt.', 'Die Niederlande betreiben seit 2017 (Zentralregierung) und 2019 (alle öffentlichen Stellen) eine verpflichtende B2G-E-Rechnung, B2B bleibt jedoch freiwillig — ein bewusst marktgetriebener Ansatz mit ungewöhnlich hoher Peppol-Verbreitung. Ein im März 2026 von der Regierung in Auftrag gegebenes Gutachten empfahl, die Pflicht auf inländisches B2B über Peppol auszuweiten, gestaffelt zwischen 2030 und 2032; die formelle Kabinettsentscheidung wurde für den Sommer 2026 erwartet, ein Gesetzentwurf für das vierte Quartal 2026. Unabhängig davon ist ViDAs grenzüberschreitende B2B-E-Rechnungs- und Meldepflicht ab dem 1. Juli 2030 bestätigtes EU-Recht, unabhängig vom inländischen Ausgang.', '🌷' FROM countries WHERE name_en = 'Netherlands';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'B2B volontaire (adoption de Peppol guidée par le marché) — B2G obligatoire depuis 2017/2019', 'Cette analyse par pays reflète les informations publiques et l''actualité disponibles à août 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. La position du cabinet néerlandais sur une obligation B2B nationale restait indécise au moment de la rédaction, une position formelle étant attendue pour l''été 2026 et un projet de loi prévu pour le quatrième trimestre 2026 — confirmez le statut actuel directement auprès de la Belastingdienst ou de Logius avant de vous y fier.', 'Les Pays-Bas ont suivi une voie guidée par le marché que la majeure partie de l''Europe n''a pas empruntée : la facturation électronique B2G est obligatoire depuis 2017, mais le B2B reste volontaire aujourd''hui, porté par une adoption de Peppol inhabituellement élevée. Cela fait désormais l''objet d''un examen actif — un rapport consultatif de mars 2026 a recommandé une obligation nationale, et la décision du cabinet est attendue de manière imminente, face à un plancher ferme de droit de l''UE à partir de juillet 2030 pour le B2B transfrontalier, quelle que soit l''issue.', 'Là où l''échange B2G a lieu, il repose sur Peppol BIS 3.0 / SI-UBL 2.0 — la même norme utilisée volontairement par la majeure partie du trafic B2B actuel, si bien que les entreprises échangeant déjà des factures Peppol avec des contreparties publiques sont largement préadaptées à ce qu''apportera la décision sur le B2B national.', 'Trois canaux desservent aujourd''hui le trafic B2G — le réseau Peppol (recommandé), Digipoort (une passerelle directe pour les fournisseurs à fort volume) et le portail fournisseurs du gouvernement (saisie manuelle pour les fournisseurs à faible volume) — tandis que l''échange B2B se fait par accord mutuel, généralement aussi via Peppol.', 'Le B2B étant volontaire aujourd''hui, l''essentiel du travail à court terme des entreprises relève de la préparation plutôt que de la conformité : confirmer la capacité Peppol, suivre la décision du cabinet sur le périmètre, et se préparer au plancher confirmé de l''UE de 2030 pour le transfrontalier, quel que soit le périmètre final de l''obligation nationale.', 'Il n''existe aujourd''hui aucun régime de sanctions B2B national car il n''existe aucune obligation B2B nationale — mais deux pressions réelles s''exercent déjà : l''exclusion contractuelle (les contreparties exigeant de plus en plus Peppol) et le plancher de l''UE qui approche, applicable quelle que soit l''issue nationale.', 'Les Pays-Bas appliquent la facturation électronique B2G obligatoire depuis 2017 (administration centrale) et 2019 (tous les organismes publics), mais le B2B reste volontaire — une approche délibérément guidée par le marché avec une adoption de Peppol inhabituellement élevée. Un rapport commandé par le gouvernement en mars 2026 a recommandé d''étendre l''obligation au B2B national sur Peppol, échelonné entre 2030 et 2032 ; la décision formelle du cabinet était attendue pour l''été 2026, avec un projet de loi prévu pour le quatrième trimestre 2026. Par ailleurs, l''obligation ViDA de facturation électronique et de déclaration transfrontalières B2B est un droit de l''UE confirmé à partir du 1er juillet 2030, quelle que soit l''issue nationale.', '🌷' FROM countries WHERE name_en = 'Netherlands';

