INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Estándar", "Peppol BIS Billing 3.0 / SI-UBL 2.0 (alineado con EN 16931)"], ["Base legal", "B2G: Directiva UE 2014/55/EU, transpuesta en 2017/2019"], ["B2B hoy", "Sin formato obligatorio — Peppol es el estándar de mercado de facto"], ["Futuro B2B (propuesto)", "EN 16931, probablemente vía Peppol, según el informe de marzo de 2026"]]', 'No existe un formato nacional neerlandés independiente que aprender — SI-UBL está totalmente alineado con Peppol BIS 3.0 internacional, de modo que una empresa ya capacitada para Peppol con una contraparte (gobierno o comercial) lo está prácticamente para todas.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["Standard", "Peppol BIS Billing 3.0 / SI-UBL 2.0 (an EN 16931 angelehnt)"], ["Rechtsgrundlage", "B2G: EU-Richtlinie 2014/55/EU, umgesetzt 2017/2019"], ["B2B heute", "Kein vorgeschriebenes Format — Peppol ist der De-facto-Marktstandard"], ["Zukünftiges B2B (Vorschlag)", "EN 16931, höchstwahrscheinlich über Peppol, laut Gutachten vom März 2026"]]', 'Es gibt kein separates niederländisches nationales Format zu erlernen — SI-UBL ist vollständig mit dem internationalen Peppol BIS 3.0 abgestimmt, sodass ein für einen Geschäftspartner (Staat oder Wirtschaft) bereits Peppol-fähiges Unternehmen im Wesentlichen für alle fähig ist.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Norme", "Peppol BIS Billing 3.0 / SI-UBL 2.0 (alignée sur l''EN 16931)"], ["Base légale", "B2G : directive UE 2014/55/EU, transposée en 2017/2019"], ["B2B aujourd''hui", "Aucun format imposé — Peppol est la norme de marché de facto"], ["B2B futur (proposé)", "EN 16931, probablement via Peppol, selon le rapport de mars 2026"]]', 'Il n''existe pas de format national néerlandais distinct à apprendre — SI-UBL est entièrement aligné sur Peppol BIS 3.0 international, si bien qu''une entreprise déjà capable de Peppol pour un partenaire (public ou commercial) l''est pour pratiquement tous.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores y registro', '[["Registro B2G", "A través de Logius (Digipoort) o un punto de acceso Peppol"], ["Identidad Peppol", "ID de participante Peppol, emitido por un proveedor de punto de acceso"], ["Organismo regulador", "Autoridad Peppol de los Países Bajos (antes SimplerInvoicing), bajo el Ministerio del Interior"], ["B2B hoy", "No se requiere registro — acuerdo bilateral entre socios comerciales"]]', 'Como el B2B no tiene mandato, no existe un registro nacional B2B en el que inscribirse — el único paso de registro formal hoy es para el tráfico B2G, o para cualquier empresa que decida obtener su propia capacidad de punto de acceso Peppol.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kennungen & Registrierung', '[["B2G-Registrierung", "Über Logius (Digipoort) oder einen Peppol-Zugangspunkt"], ["Peppol-Identität", "Peppol-Teilnehmer-ID, ausgestellt von einem Zugangspunktanbieter"], ["Zuständige Stelle", "Niederländische Peppol-Behörde (vormals SimplerInvoicing), unter dem Innenministerium"], ["B2B heute", "Keine Registrierung erforderlich — bilaterale Vereinbarung zwischen Geschäftspartnern"]]', 'Da B2B keiner Pflicht unterliegt, gibt es kein nationales B2B-Register, in das man sich eintragen müsste — der einzige formelle Registrierungsschritt betrifft heute den B2G-Verkehr oder Unternehmen, die sich für eine eigene Peppol-Zugangspunkt-Fähigkeit entscheiden.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants et enregistrement', '[["Enregistrement B2G", "Via Logius (Digipoort) ou un point d''accès Peppol"], ["Identité Peppol", "ID de participant Peppol, délivré par un fournisseur de point d''accès"], ["Organisme compétent", "Autorité Peppol des Pays-Bas (anciennement SimplerInvoicing), sous le ministère de l''Intérieur"], ["B2B aujourd''hui", "Aucun enregistrement requis — accord bilatéral entre partenaires commerciaux"]]', 'Le B2B n''étant soumis à aucune obligation, il n''existe pas de registre national B2B où s''inscrire — la seule étape d''enregistrement formelle aujourd''hui concerne le trafic B2G, ou toute entreprise choisissant d''obtenir sa propre capacité de point d''accès Peppol.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio', '[["B2G", "Modelo completo de factura básica EN 16931 vía Peppol BIS 3.0"], ["B2B hoy", "Lo que acuerden las partes — habitualmente los mismos campos de Peppol BIS 3.0 en la práctica"], ["Archivo", "7 años, requisito estándar neerlandés de conservación de registros"]]', 'Como Peppol BIS 3.0 ya domina el intercambio B2B voluntario, el contenido de las facturas de la mayoría de las empresas ya tiene en la práctica la forma de EN 16931, incluso sin que exista una obligación legal que lo imponga.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalte', '[["B2G", "Vollständiges EN-16931-Kernrechnungsmodell über Peppol BIS 3.0"], ["B2B heute", "Was die Handelspartner vereinbaren — in der Praxis meist dieselben Peppol-BIS-3.0-Felder"], ["Archivierung", "7 Jahre, niederländische Standard-Aufbewahrungspflicht"]]', 'Da Peppol BIS 3.0 den freiwilligen B2B-Austausch bereits dominiert, hat der Rechnungsinhalt der meisten Unternehmen in der Praxis bereits EN-16931-Form, auch ohne gesetzliche Pflicht.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire', '[["B2G", "Modèle complet de facture de base EN 16931 via Peppol BIS 3.0"], ["B2B aujourd''hui", "Ce que conviennent les parties — généralement les mêmes champs Peppol BIS 3.0 en pratique"], ["Archivage", "7 ans, exigence standard néerlandaise de conservation des documents"]]', 'Peppol BIS 3.0 dominant déjà l''échange B2B volontaire, le contenu des factures de la plupart des entreprises a déjà en pratique la forme de l''EN 16931, même sans obligation légale.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Modelo de red', '[["Modelo B2G", "Red Peppol de cuatro esquinas, o integración directa con Digipoort"], ["Modelo B2B", "Intercambio bilateral voluntario, típicamente también sobre Peppol"], ["Reporte en tiempo real", "Ninguno hoy — los Países Bajos no tienen régimen nacional de compensación o CTC"], ["Autoridad Peppol", "Autoridad Peppol de los Países Bajos (antes SimplerInvoicing)"]]', 'A diferencia de la mayoría del rastreador, aquí no hay un modelo de compensación que describir para el B2B — las facturas se mueven directamente entre los sistemas de las partes comerciales, sin que la autoridad tributaria tenga visibilidad en tiempo real, un contraste deliberado con Bélgica, Francia, Italia y Polonia.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Netzwerkmodell', '[["B2G-Modell", "Peppol-Vier-Ecken-Netzwerk oder direkte Digipoort-Integration"], ["B2B-Modell", "Freiwilliger bilateraler Austausch, meist ebenfalls über Peppol"], ["Echtzeit-Meldung", "Heute keine — die Niederlande haben kein nationales Clearance- oder CTC-Regime"], ["Peppol-Behörde", "Niederländische Peppol-Behörde (vormals SimplerInvoicing)"]]', 'Anders als bei den meisten Ländern im Tracker gibt es hier kein Clearance-Modell für B2B zu beschreiben — Rechnungen bewegen sich direkt zwischen den Systemen der Handelspartner, ohne dass die Steuerbehörde Echtzeit-Einblick erhält, ein bewusster Kontrast zu Belgien, Frankreich, Italien und Polen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Modèle de réseau', '[["Modèle B2G", "Réseau Peppol à quatre coins, ou intégration directe avec Digipoort"], ["Modèle B2B", "Échange bilatéral volontaire, généralement aussi via Peppol"], ["Déclaration en temps réel", "Aucune aujourd''hui — les Pays-Bas n''ont pas de régime national de validation préalable ou de CTC"], ["Autorité Peppol", "Autorité Peppol des Pays-Bas (anciennement SimplerInvoicing)"]]', 'Contrairement à la plupart des pays du tracker, il n''y a ici aucun modèle de validation préalable à décrire pour le B2B — les factures circulent directement entre les systèmes des partenaires commerciaux, sans que l''administration fiscale ait de visibilité en temps réel, un contraste délibéré avec la Belgique, la France, l''Italie et la Pologne.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Canales', '[["Red Peppol", "El canal recomendado tanto para B2G como para el B2B voluntario"], ["Digipoort", "Pasarela directa para proveedores B2G de gran volumen (aprox. 50+ facturas/semana)"], ["Portal de Proveedores del Gobierno", "Entrada manual para proveedores B2G de bajo volumen"], ["ROAP", "Punto de Acceso Peppol del Gobierno Central — el propio punto de acceso Peppol del gobierno central"]]', 'La estructura de tres niveles de canales B2G (Peppol / Digipoort / portal manual) existe específicamente para que los proveedores más pequeños no queden excluidos por el mandato — un patrón de diseño digno de mención dado que el mandato B2B nacional en discusión necesitaría algo similar.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kanäle', '[["Peppol-Netzwerk", "Der empfohlene Kanal sowohl für B2G als auch für freiwilliges B2B"], ["Digipoort", "Direktgateway für B2G-Lieferanten mit hohem Volumen (etwa 50+ Rechnungen/Woche)"], ["Regierungslieferantenportal", "Manuelle Web-Eingabe für B2G-Lieferanten mit geringem Volumen"], ["ROAP", "Rijksoverheid-Zugangspunkt auf Peppol — der eigene Peppol-Zugangspunkt der Zentralregierung"]]', 'Die dreistufige B2G-Kanalstruktur (Peppol / Digipoort / manuelles Portal) existiert speziell, damit kleinere Lieferanten durch die Pflicht nicht ausgeschlossen werden — ein Gestaltungsmuster, das angesichts der diskutierten inländischen B2B-Pflicht Beachtung verdient.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Canaux', '[["Réseau Peppol", "Le canal recommandé pour le B2G comme pour le B2B volontaire"], ["Digipoort", "Passerelle directe pour les fournisseurs B2G à fort volume (environ 50+ factures/semaine)"], ["Portail fournisseurs du gouvernement", "Saisie manuelle pour les fournisseurs B2G à faible volume"], ["ROAP", "Point d''accès Peppol du gouvernement central (Rijksoverheid) — son propre point d''accès Peppol"]]', 'La structure à trois niveaux des canaux B2G (Peppol / Digipoort / portail manuel) existe spécifiquement pour que les petits fournisseurs ne soient pas exclus par l''obligation — un choix de conception à noter, l''obligation B2B nationale en discussion nécessiterait probablement quelque chose de similaire.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'La decisión nacional pendiente', '[["En revisión", "ViDA-A (solo transfronterizo) frente a ViDA-B (extensión al B2B nacional)"], ["Recomendación consultiva", "ViDA-B, sobre Peppol, escalonado entre 2030 y 2032 (informe de marzo de 2026)"], ["Decisión del gabinete", "Esperada para el verano de 2026 (aún no anunciada formalmente al momento de escribir esto)"], ["Suelo firme en cualquier caso", "1 de julio de 2030 — B2B transfronterizo de ViDA, derecho de la UE confirmado"]]', 'Esta es la única entrada de esta página que está genuinamente por decidir — siga la página de fuentes y el panel del rastreador para conocer la postura formal del gabinete una vez anunciada, ya que determinará si prácticamente todas las empresas neerlandesas registradas a efectos de IVA necesitarán finalmente capacidad Peppol, o solo las que comercian de forma transfronteriza.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Die ausstehende inländische Entscheidung', '[["In Prüfung", "ViDA-A (nur grenzüberschreitend) vs. ViDA-B (Ausweitung auf inländisches B2B)"], ["Empfehlung des Gutachtens", "ViDA-B, auf Peppol, gestaffelt 2030–2032 (Gutachten vom März 2026)"], ["Kabinettsentscheidung", "Für den Sommer 2026 erwartet (zum Zeitpunkt der Abfassung noch nicht formell verkündet)"], ["Feste Untergrenze in jedem Fall", "1. Juli 2030 — grenzüberschreitendes B2B nach ViDA, bestätigtes EU-Recht"]]', 'Dies ist der einzige Eintrag auf dieser Seite, der wirklich noch offen ist — verfolgen Sie die Quellenseite und die Tracker-Tafel auf die formelle Position des Kabinetts, sobald sie bekanntgegeben wird, denn sie entscheidet, ob praktisch jedes umsatzsteuerregistrierte niederländische Unternehmen letztlich Peppol-Fähigkeit benötigt oder nur die grenzüberschreitend Handelnden.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'La décision nationale en attente', '[["En cours d''examen", "ViDA-A (transfrontalier uniquement) contre ViDA-B (extension au B2B national)"], ["Recommandation du rapport", "ViDA-B, sur Peppol, échelonné entre 2030 et 2032 (rapport de mars 2026)"], ["Décision du cabinet", "Attendue pour l''été 2026 (non encore annoncée formellement au moment de la rédaction)"], ["Plancher ferme dans tous les cas", "1er juillet 2030 — B2B transfrontalier ViDA, droit de l''UE confirmé"]]', 'C''est la seule entrée de cette page qui soit véritablement indécise — suivez la page des sources et le tableau du tracker pour la position formelle du cabinet une fois annoncée, car elle déterminera si pratiquement toutes les entreprises néerlandaises assujetties à la TVA auront finalement besoin de la capacité Peppol, ou seulement celles opérant en transfrontalier.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🤝 Exclusión contractual, no multas legales', NULL, NULL, 'No existe una sanción legal por incumplimiento B2B hoy, porque no existe una obligación legal B2B — pero las grandes contrapartes exigen cada vez más la capacidad Peppol como condición de contratación. En la práctica, el coste de quedarse fuera del sistema voluntario es perder negocio, no una multa.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🤝 Vertraglicher Ausschluss, keine gesetzlichen Strafen', NULL, NULL, 'Es gibt heute keine gesetzliche Strafe für B2B-Nichteinhaltung, weil es keine gesetzliche B2B-Pflicht gibt — aber wichtige Geschäftspartner verlangen zunehmend Peppol-Fähigkeit als Beschaffungsbedingung. In der Praxis besteht der Preis für das Fernbleiben vom freiwilligen System im Verlust von Geschäft, nicht in einer Geldstrafe.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🤝 Exclusion contractuelle, pas d''amendes légales', NULL, NULL, 'Il n''existe aujourd''hui aucune sanction légale pour non-conformité B2B, car il n''existe aucune obligation légale B2B — mais les grandes contreparties exigent de plus en plus la capacité Peppol comme condition d''achat. En pratique, le coût de rester en dehors du système volontaire est la perte d''affaires, pas une amende.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🇪🇺 El suelo de la UE que se acerca', NULL, NULL, 'Con independencia de lo que decidan los Países Bajos sobre el B2B nacional, el requisito transfronterizo de ViDA es derecho de la UE confirmado desde el 1 de julio de 2030 — toda empresa neerlandesa que realice comercio B2B intracomunitario necesitará facturación electrónica y reporte digital conformes con EN 16931 para esas operaciones, con o sin mandato.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🇪🇺 Die näherrückende EU-Untergrenze', NULL, NULL, 'Unabhängig davon, was die Niederlande beim inländischen B2B entscheiden, ist die grenzüberschreitende ViDA-Anforderung ab dem 1. Juli 2030 bestätigtes EU-Recht — jedes niederländische Unternehmen mit innergemeinschaftlichem B2B-Handel benötigt für diese Umsätze EN-16931-konforme E-Rechnung und digitale Meldung, Pflicht hin oder her.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🇪🇺 Le plancher de l''UE qui approche', NULL, NULL, 'Quelle que soit la décision des Pays-Bas sur le B2B national, l''exigence transfrontalière de ViDA est un droit de l''UE confirmé à partir du 1er juillet 2030 — toute entreprise néerlandaise réalisant du commerce B2B intracommunautaire aura besoin d''une facturation électronique et d''une déclaration numérique conformes à l''EN 16931 pour ces opérations, obligation ou non.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⚖️ Excepciones B2G', NULL, NULL, 'Para el tráfico B2G, las facturas no conformes pueden rechazarse conforme a las normas de contratación pública — el mecanismo más parecido a la aplicación que existe hoy, y limitado al comercio con el gobierno más que a la economía en general.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚖️ B2G-Ausnahmen', NULL, NULL, 'Für den B2G-Verkehr können nicht konforme Rechnungen nach den Vorschriften des öffentlichen Beschaffungswesens abgelehnt werden — der einzige heute existierende Durchsetzungsmechanismus, beschränkt auf den Handel mit dem Staat statt auf die gesamte Wirtschaft.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚖️ Exceptions B2G', NULL, NULL, 'Pour le trafic B2G, les factures non conformes peuvent être rejetées selon les règles de la commande publique — le mécanisme le plus proche d''une application existant aujourd''hui, limité au commerce avec l''État plutôt qu''à l''ensemble de l''économie.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Netherlands' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme su capacidad Peppol actual', 'Dado que la mayor parte del tráfico B2B neerlandés ya funciona voluntariamente sobre Peppol, compruebe si su ERP o software de contabilidad ya admite BIS 3.0 / SI-UBL 2.0 — muchas plataformas neerlandesas habituales lo hacen de forma nativa.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Netherlands' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie Ihre aktuelle Peppol-Fähigkeit', 'Da der meiste niederländische B2B-Verkehr bereits freiwillig über Peppol läuft, prüfen Sie, ob Ihr ERP- oder Buchhaltungssoftware bereits BIS 3.0 / SI-UBL 2.0 unterstützt — viele gängige niederländische Plattformen tun dies nativ.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Netherlands' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez votre capacité Peppol actuelle', 'La majeure partie du trafic B2B néerlandais fonctionnant déjà volontairement sur Peppol, vérifiez si votre ERP ou logiciel comptable prend déjà en charge BIS 3.0 / SI-UBL 2.0 — de nombreuses plateformes néerlandaises courantes le font nativement.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Netherlands' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Establezca o verifique su canal B2G si corresponde', 'Los proveedores de organismos públicos neerlandeses deben confirmar que utilizan correctamente Peppol, Digipoort o el Portal de Proveedores del Gobierno, y que existe capacidad de recepción para los organismos subcentrales.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Netherlands' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie Ihren B2G-Kanal ein oder überprüfen Sie ihn, falls zutreffend', 'Lieferanten niederländischer öffentlicher Stellen sollten bestätigen, dass sie Peppol, Digipoort oder das Regierungslieferantenportal korrekt nutzen, und dass die Empfangsfähigkeit für nachgeordnete Stellen vorhanden ist.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Netherlands' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Établissez ou vérifiez votre canal B2G le cas échéant', 'Les fournisseurs d''organismes publics néerlandais doivent confirmer qu''ils utilisent correctement Peppol, Digipoort ou le portail fournisseurs du gouvernement, et que la capacité de réception est en place pour les organismes infra-étatiques.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Netherlands' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Siga la decisión ViDA-A/ViDA-B del gabinete', 'Esta es la pregunta abierta más importante para la facturación electrónica neerlandesa — la decisión sobre el alcance nacional determina si el próximo mandato cubrirá solo el comercio transfronterizo o prácticamente a todas las empresas registradas a efectos de IVA.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Netherlands' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Verfolgen Sie die ViDA-A/ViDA-B-Entscheidung des Kabinetts', 'Dies ist die wichtigste offene Frage für die niederländische E-Rechnung — die Umfangsentscheidung bestimmt, ob die kommende Pflicht nur den grenzüberschreitenden Handel oder praktisch jedes umsatzsteuerregistrierte Unternehmen abdeckt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Netherlands' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Suivez la décision ViDA-A/ViDA-B du cabinet', 'C''est la question ouverte la plus déterminante pour la facturation électronique néerlandaise — la décision sur le périmètre national détermine si la future obligation ne couvrira que le commerce transfrontalier ou pratiquement toutes les entreprises assujetties à la TVA.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Netherlands' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Prepárese para el suelo transfronterizo de 2030 en cualquier caso', 'Incluso si los Países Bajos optan por el alcance mínimo de ViDA-A, toda empresa que realice comercio B2B intracomunitario necesitará capacidad de facturación electrónica y reporte digital conforme a EN 16931 desde el 1 de julio de 2030 — esta fecha la fija la directiva de la UE, no la discreción neerlandesa.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Netherlands' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bereiten Sie sich in jedem Fall auf die grenzüberschreitende Untergrenze 2030 vor', 'Selbst wenn sich die Niederlande für den minimalen ViDA-A-Umfang entscheiden, benötigt jedes Unternehmen mit innergemeinschaftlichem B2B-Handel ab dem 1. Juli 2030 EN-16931-konforme E-Rechnungs- und digitale Meldefähigkeit — dieses Datum ist durch EU-Richtlinie festgelegt, nicht durch niederländisches Ermessen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Netherlands' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Préparez-vous au plancher transfrontalier de 2030 dans tous les cas', 'Même si les Pays-Bas optent pour le périmètre minimal ViDA-A, toute entreprise réalisant du commerce B2B intracommunautaire aura besoin d''une capacité de facturation électronique et de déclaration numérique conforme à l''EN 16931 dès le 1er juillet 2030 — cette date est fixée par la directive de l''UE, non par la discrétion néerlandaise.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Netherlands' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Revise los contratos con contrapartes en busca de requisitos Peppol', 'Con una adopción ya alta y en aumento, espere que más socios comerciales conviertan la capacidad Peppol en una condición de contratación antes de cualquier mandato nacional formal.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Netherlands' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Überprüfen Sie Geschäftspartnerverträge auf Peppol-Anforderungen', 'Bei bereits hoher und steigender Verbreitung ist damit zu rechnen, dass mehr Handelspartner die Peppol-Fähigkeit zur Beschaffungsbedingung machen, noch bevor es eine formelle inländische Pflicht gibt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Netherlands' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Réexaminez les contrats avec vos partenaires pour les exigences Peppol', 'Avec une adoption déjà élevée et croissante, attendez-vous à ce que davantage de partenaires commerciaux fassent de la capacité Peppol une condition d''achat avant même toute obligation nationale formelle.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Netherlands' AND ds.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Logius — e-Factureren' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Netherlands' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'Logius — E-Rechnung (e-Factureren)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Netherlands' AND dp.sort_order = 0;
